`timescale 1ns/1ps
// Chip-level control-plane simulation, one section per mode family (digital work item 2, rows TOP-1, MW-1..19):
// the real rtl/pt_digital_macro.sv against the stub analog top generated from integration/top/pt_chip.conn. Each
// section writes registers over SPI and checks that the right analog cell pins take the right values, with a
// negative control (island off, wrong order rejected by a rule, interlock holding a pin low, or "no other pin moved").
// Register addresses / positions come from spec/register-map.json (tb_fields.svh, generated by
// verification/check_top_modes.py, which also runs decode mutants that this bench must FAIL on).
`include "pt_regmap_defs.svh"
module tb_top_modes;
 reg rst_pad = 0, sclk = 0, cs_n = 1, mosi = 0, ref_clk = 0, h2d_clk = 0, fault_pin = 0; wire miso, miso_oe;
 supply1 VDD; supply0 VSS;
`include "tb_ctl.svh"
`include "tb_fields.svh"
 wire [5:0] island_en, island_on, island_off;
 wire [57:0] atb0_sw, atb1_sw; wire [1:0] atb0_grp; wire [4:0] atb1_grp; wire atb0_en, atb1_en;
 wire por_n, wired_on_ext, wire_rx_ptrim_en, rx_en_aux, rx_en_wtx_ext;
 wire s_pg_wired_rx, s_pg_wired_cap, s_pg_wired_tx, s_pg_rf_rx, s_pg_rf_tx, s_pg_lod, s_pg_lo, s_pg_pll, s_pg_conv, s_pg_debug;
 always #10 ref_clk = ~ref_clk;                       // 50 MHz reference (rx_ref_in output in the real chip)
 reg wtx_clk = 0; always #10.4 wtx_clk = analog.p_wiredtx__SER_EN ? ~wtx_clk : 1'b0;   // WORD_CLK40 runs only with SER_EN
 reg aosc = 0; always #10.5 aosc = analog.p_aosc__EN ? ~aosc : 1'b0;                    // always-on oscillator
 pt_digital_macro dut(.reset_n_pad(rst_pad), .por_n(por_n), .por_bypass(1'b0), .spi_sclk(sclk), .spi_cs_n(cs_n), .spi_mosi(mosi),
  .spi_miso(miso), .spi_miso_oe(miso_oe), .island_en(island_en), .island_on(island_on), .island_off(island_off),
  .s_pg_wired_rx(s_pg_wired_rx), .s_pg_wired_cap(s_pg_wired_cap), .s_pg_wired_tx(s_pg_wired_tx), .s_pg_rf_rx(s_pg_rf_rx),
  .s_pg_rf_tx(s_pg_rf_tx), .s_pg_lod(s_pg_lod), .s_pg_lo(s_pg_lo), .s_pg_pll(s_pg_pll), .s_pg_conv(s_pg_conv), .s_pg_debug(s_pg_debug),
  .wired_on_ext(wired_on_ext), .atb0_sw(atb0_sw), .atb1_sw(atb1_sw), .atb0_grp(atb0_grp),
  .atb1_grp(atb1_grp), .atb0_en(atb0_en), .atb1_en(atb1_en), .wire_rx_ptrim_en(wire_rx_ptrim_en), .fault(fault_pin),
  .rx_en_aux(rx_en_aux), .rx_en_wtx_ext(rx_en_wtx_ext),
  .host_word_clk(1'b0), .h2d_clk(h2d_clk), .h2d_pin(10'b0), .ref_clk(ref_clk), .wire_rx_clk(1'b0), .wire_tx_clk(wtx_clk),
  .rf_rx_clk(1'b0), .rf_tx_clk(1'b0), .ct_wclk(1'b0), .fc_src({1'b0, aosc, 4'b0}), .wire_rx_data(40'b0), .wire_rx_edge(20'b0),
  .rf_rx_sample(24'b0), .rf_rx_sample_b(24'b0), .rf_rx_ph_i(1'b0), .rf_rx_ph_q(1'b0),
  .s_pll_tx_lock(1'b0), .s_pll_cdr_lock(1'b0), .s_ref_present(1'b1), .s_refbuf_ready(1'b0), .s_adc_i_ovl(1'b0), .s_adc_i_b_ovl(1'b0),
  .s_adc_q_ovl(1'b0), .s_adc_q_b_ovl(1'b0), .s_adc_i_done(1'b0), .s_adc_i_b_done(1'b0), .s_adc_q_done(1'b0), .s_adc_q_b_done(1'b0),
  .s_detect_diff_pos(1'b0), .s_detect_diff_neg(1'b0), .s_detect_se_p(1'b0), .s_detect_se_n(1'b0), .s_wrx_slp(1'b0), .s_wrx_slm(1'b0),
  .s_wtx_ext_data(1'b0), .s_aux_present(1'b0), .s_wtx_ext_present(1'b0), `PT_CTL_CONNECT);
 pt_analog_top_stub analog(.VDD(VDD), .VSS(VSS), .island_en(island_en), .island_on(island_on), .island_off(island_off),
  .s_pg_wired_rx(s_pg_wired_rx), .s_pg_wired_cap(s_pg_wired_cap), .s_pg_wired_tx(s_pg_wired_tx), .s_pg_rf_rx(s_pg_rf_rx),
  .s_pg_rf_tx(s_pg_rf_tx), .s_pg_lod(s_pg_lod), .s_pg_lo(s_pg_lo), .s_pg_pll(s_pg_pll), .s_pg_conv(s_pg_conv), .s_pg_debug(s_pg_debug),
  .wired_on_ext(wired_on_ext), .atb0_sw(atb0_sw), .atb1_sw(atb1_sw), .atb0_grp(atb0_grp), .rx_en_aux(rx_en_aux), .rx_en_wtx_ext(rx_en_wtx_ext),
  .atb1_grp(atb1_grp), .atb0_en(atb0_en), .atb1_en(atb1_en), .wire_rx_ptrim_en(wire_rx_ptrim_en), .por_n(por_n), `PT_CTL_CONNECT);

 integer errors = 0, checks = 0;
 task chk(input cond, input [799:0] msg);
  begin checks = checks + 1; if (cond !== 1'b1) begin $display("FAIL: %0s", msg); errors = errors + 1; end end
 endtask
 task spi(input [7:0] command, address, input [15:0] value, output [15:0] result);
  reg [31:0] tx; integer i;
  begin
   tx = {command, address, value}; result = 0; cs_n = 0; #50;
   for (i = 31; i >= 0; i = i-1) begin mosi = tx[i]; #50; sclk = 1; #50; if (i < 16) result[i] = miso; sclk = 0; end
   #50; cs_n = 1; mosi = 0; #50;
  end
 endtask
 reg [15:0] r; reg [15:0] shadow [0:255];
 task wr(input [7:0] a, input [15:0] v); spi(8'h80, a, v, r); endtask
 // set one field (address, lsb, width from tb_fields.svh): read-modify-write on the bench's shadow copy
 task setf(input [7:0] a, input [4:0] lsb, input [4:0] w, input [15:0] v);
  reg [15:0] m;
  begin m = ((16'd1 << w) - 16'd1) << lsb; shadow[a] = (shadow[a] & ~m) | ((v << lsb) & m); wr(a, shadow[a]); end
 endtask
 // COMMIT; ok = 1 expects acceptance, 0 expects a rejection (the pending shadow stays; the bench then corrects the field)
 task commit(input ok, input [799:0] what);
  begin
   wr(8'h06, 16'h1); spi(8'h00, 8'h0C, 16'h0, r);
   chk((r[15:8] == 8'h00) === ok, what);
   if (r[15:8] != 8'h00) begin if (ok) $display("   commit result %h", r[15:8]); wr(8'h05, 16'h7F); end
  end
 endtask
 reg [$bits(ctl_all)-1:0] snap;
 function integer ones(input [$bits(ctl_all)-1:0] v); integer k; begin ones = 0; for (k = 0; k < $bits(ctl_all); k = k+1) ones = ones+v[k]; end endfunction
 task dummy_clocks(input integer n); integer k; begin for (k = 0; k < n; k = k+1) spi(8'h00, 8'h00, 16'h0, r); end endtask
 // analog pin groups
 wire [3:0] lna_ct = {analog.p_lna__ct3, analog.p_lna__ct2, analog.p_lna__ct1, analog.p_lna__ct0};
 wire [5:0] lna_code = {analog.p_lna__gain_lo, analog.p_lna__att4, analog.p_lna__att3, analog.p_lna__att2, analog.p_lna__att1, analog.p_lna__att0};
 wire [5:0] bbi_k = {analog.p_bbfilter_i__gain5, analog.p_bbfilter_i__gain4, analog.p_bbfilter_i__gain3, analog.p_bbfilter_i__gain2, analog.p_bbfilter_i__gain1, analog.p_bbfilter_i__gain0};
 wire [5:0] bbq_k = {analog.p_bbfilter_q__gain5, analog.p_bbfilter_q__gain4, analog.p_bbfilter_q__gain3, analog.p_bbfilter_q__gain2, analog.p_bbfilter_q__gain1, analog.p_bbfilter_q__gain0};
 wire [6:0] bbi_cut = {analog.p_bbfilter_i__bw3, analog.p_bbfilter_i__bw2, analog.p_bbfilter_i__bw1, analog.p_bbfilter_i__bw0, analog.p_bbfilter_i__fc_fine2, analog.p_bbfilter_i__fc_fine1, analog.p_bbfilter_i__fc_fine0};
 wire [3:0] bbi_qt = {analog.p_bbfilter_i__qt3, analog.p_bbfilter_i__qt2, analog.p_bbfilter_i__qt1, analog.p_bbfilter_i__qt0};
 wire [2:0] lo_pins = {analog.p_lo_ext__CMLSEL, analog.p_lo_ext__INT, analog.p_lo_ext__EXT};
 wire [5:0] lo_n = {analog.p_lo_mmd__N5, analog.p_lo_mmd__N4, analog.p_lo_mmd__N3, analog.p_lo_mmd__N2, analog.p_lo_mmd__N1, analog.p_lo_mmd__N0};
 wire [3:0] qvco_band = {analog.p_qvco__BAND3, analog.p_qvco__BAND2, analog.p_qvco__BAND1, analog.p_qvco__BAND0};
 wire [2:0] mux_ps = {analog.p_clockmux__PS_H2D, analog.p_clockmux__PS_AUX, analog.p_clockmux__PS_REF};
 wire [3:0] mux_cs = {analog.p_clockmux__CS_HF, analog.p_clockmux__CS_AUX, analog.p_clockmux__CS_REF, analog.p_clockmux__CS_INT};
 wire [1:0] mux_hs = {analog.p_clockmux__HS_HF, analog.p_clockmux__HS_INT};
 wire [3:0] mux_ws = {analog.p_clockmux__WS_WCK, analog.p_clockmux__WS_AUX, analog.p_clockmux__WS_REF, analog.p_clockmux__WS_PLL};
 wire [4:0] presc_conv = {analog.p_prescale_conv__EN, analog.p_prescale_conv__D16, analog.p_prescale_conv__D8, analog.p_prescale_conv__D4, analog.p_prescale_conv__D2};
 wire [4:0] presc_host = {analog.p_prescale__EN, analog.p_prescale__D16, analog.p_prescale__D8, analog.p_prescale__D4, analog.p_prescale__D2};
 wire [3:0] hs_trim = {analog.p_termination__hs_trim3, analog.p_termination__hs_trim2, analog.p_termination__hs_trim1, analog.p_termination__hs_trim0};
 wire [9:0] trim_e2 = {analog.p_slicer__trim_e2_f3, analog.p_slicer__trim_e2_f2, analog.p_slicer__trim_e2_f1, analog.p_slicer__trim_e2_f0, analog.p_slicer__trim_e2_n2,
                       analog.p_slicer__trim_e2_n1, analog.p_slicer__trim_e2_n0, analog.p_slicer__trim_e2_p2, analog.p_slicer__trim_e2_p1, analog.p_slicer__trim_e2_p0};
 wire [7:0] vth_a = {analog.p_vthdac__A7, analog.p_vthdac__A6, analog.p_vthdac__A5, analog.p_vthdac__A4, analog.p_vthdac__A3, analog.p_vthdac__A2, analog.p_vthdac__A1, analog.p_vthdac__A0};
 wire [2:0] psel = {analog.p_wrx_cap__PSEL2, analog.p_wrx_cap__PSEL1, analog.p_wrx_cap__PSEL0};
 wire [3:0] obs_s = {analog.p_clk_obs__S3, analog.p_clk_obs__S2, analog.p_clk_obs__S1, analog.p_clk_obs__S0};
 wire [5:0] obs_pre = {analog.p_obs_pre4_cdr__EN, analog.p_obs_pre4_pll__EN, analog.p_obs_pre4_aux__EN, analog.p_obs_pre4_ref__EN, analog.p_obs_pre4_wsmp__EN, analog.p_obs_pre4_wire__EN};
 wire [3:0] rfd_g = {analog.p_rfdriver__g3, analog.p_rfdriver__g2, analog.p_rfdriver__g1, analog.p_rfdriver__g0};
 integer t_en, t_ser, t_main;   // times of the last rising edge of the three wired TX bring-up pins
 always @(posedge analog.p_pll_tx__EN) t_en = $time;
 always @(posedge analog.p_wiredtx__SER_EN) t_ser = $time;
 always @(posedge analog.p_attached_tx_interlock__REQ_MAIN) t_main = $time;

 initial begin
  `PT_TB_SHADOW_RESET
  #20; rst_pad = 1; #20; rst_pad = 0; #50; rst_pad = 1; #200;
  // ================= 0. reset: every analog control pin is 0 (islands off, always-on blocks off) =================
  // the one port that is 1 by design: the pull-down control of the tri-state CLK_OBS node (core rail)
  // only the always-on trims with a non-zero safe default (bias generator, bandgap trim) and the CLK_OBS pull-down control are 1
  chk(ctl_all === `PT_TB_CTL_RESET_OFF, "reset: a control port of a switched island or an always-on enable is not 0");
  chk(island_en === 6'd0 && island_on === 6'd0 && atb0_sw === 0 && atb1_sw === 0, "reset: island or ATB switch on");
  chk(analog.p_aosc__EN === 1'b0 && analog.p_core_bias__C_core_refchain_bgap_ena === 1'b0, "reset: always-on enables not 0");
  chk(wire_rx_ptrim_en === 1'b0 && rx_en_aux === 1'b0 && rx_en_wtx_ext === 1'b0, "reset: ptrim / receiver enables not 0");
  // every island on (stub switches: PG = EN): the cell-safe resets of ctl_ports.txt appear at the ports
  setf(`F_DEBUG_ISLAND_POWER__WIRED, 1); setf(`F_DEBUG_ISLAND_POWER__RF, 1); setf(`F_DEBUG_ISLAND_POWER__PLL, 1);
  setf(`F_DEBUG_ISLAND_POWER__CONV, 1); setf(`F_DEBUG_ISLAND_POWER__DEBUG, 1); commit(1, "islands on");
  chk(island_on === 6'b110111, "islands did not come on through the stub switches");
  chk(ctl_all === `PT_TB_CTL_RESET, "islands on: control ports differ from the reset column of ctl_ports.txt");
  chk(analog.p_lna__en === 0 && analog.p_adc_i__EN === 0 && analog.p_dac_i__EN === 0 && analog.p_rfdriver__en === 0 && analog.p_pll_tx__EN === 0 &&
      analog.p_pll_cdr__EN === 0 && analog.p_wiredtx__SER_EN === 0 && analog.p_attached_tx_interlock__REQ_MAIN === 0 && analog.p_qvco__EN === 0 &&
      analog.p_ctle__ctle_en === 0 && analog.p_slicer__slicer_en === 0 && analog.p_usb_txdrv__HS_EN === 0 && analog.p_usb_txdrv__FS_EN === 0,
      "islands on: a block enable is set at the reset configuration");
  chk(analog.p_rfdriver__mute === 1'b1 && analog.p_dac_i__HOLD_ZERO === 1'b1 && bbi_k === 6'd4 && bbi_cut === 7'd8 && bbi_qt === 4'd6 && hs_trim === 4'd5,
      "islands on: safe defaults (mute, hold_zero, PGA 0 dB, cut 8, qt 6, hs_trim 5) not at the pins");

  // ================= 1. always-on: bias chain with the bandgap-before-consumers interlock, aosc =================
  setf(`F_CORE_REFCHAIN__BGAP_ENA, 1); setf(`F_CORE_REFCHAIN__DIST_EN_RF, 1); setf(`F_CORE_BIASGEN__REF_SEL_VBG, 1); setf(`F_CORE_BIASGEN__ENA, 1);
  commit(1, "bias chain in one commit");
  chk(analog.p_core_bias__C_core_refchain_bgap_ena === 1'b1 && analog.p_core_bias__C_core_biasgen_ena === 1'b1, "bandgap / biasgen enable did not reach core_bias");
  chk(analog.p_core_bias__C_core_refchain_dist_en_rf === 1'b0 && analog.p_core_bias__C_core_biasgen_ref_sel_vbg === 1'b0,
      "interlock: bandgap consumers on in the same commit as the bandgap (negative control)");
  dummy_clocks(9);
  chk(analog.p_core_bias__C_core_refchain_dist_en_rf === 1'b1 && analog.p_core_bias__C_core_biasgen_ref_sel_vbg === 1'b1, "interlock did not release after 256 SCLK cycles");
  setf(`F_CORE_AOSC__ENABLE, 1); commit(1, "aosc on");
  chk(analog.p_aosc__EN === 1'b1, "aosc EN did not follow core.aosc.enable");

  // ================= 2. RF receive, die-1 baseline: external LO through the CML driver, host_follow clocks =================
  snap = ctl_all;
  setf(`F_RFPLL_CONFIG__LO_MODE, 3); commit(1, "lo_mode external_cml");
  chk(lo_pins === 3'b111 && analog.p_qvco__CMLSEL === 1'b1 && analog.p_qvco__EN === 1'b0, "lo_mode 3: EXT/INT/CMLSEL not 111 or QVCO enabled");
  setf(`F_REFINPUT_STATE__STATE, 2); commit(1, "refinput active");
  chk(analog.p_rx_ref_in__EN === 1'b0, "REF_IN clock receiver enabled while REF_IN carries the external LO (negative control)");
  setf(`F_DEBUG_CLK_SELECT__CONV_SAMPLE, 3); commit(0, "rule lo_pads_vs_forwarded_clock: AUX_CLK as a clock with an external LO must be rejected");
  setf(`F_DEBUG_CLK_SELECT__CONV_SAMPLE, 0);
  // clocks: H2D_CLK -> ring reference, line ring x16 /4 -> CONV_INT and HOST_INT (host_follow on the TX ring, D-HF)
  setf(`F_CLOCKMUX_CONFIG__RING_REF, 3); setf(`F_CLOCKMUX_CONFIG__CONV_PRESCALE, 2); setf(`F_CLOCKMUX_CONFIG__HOST_PRESCALE, 2);
  setf(`F_DEBUG_CLK_SELECT__WIRE_LINE, 1); setf(`F_DEBUG_CLK_SELECT__CONV_SAMPLE, 1); setf(`F_DEBUG_CLK_SELECT__HOST_CLK, 1); commit(1, "host_follow clock selects");
  chk(mux_ws === 4'b0001, "clockmux WS_PLL: the line ring must feed the prescalers (WIRE_CK) in the RF baseline too");
  chk(mux_ps === 3'b100 && mux_cs === 4'b0001 && mux_hs === 2'b01, "clockmux one-hot selects wrong (PS_H2D / CS_INT / HS_INT)");
  chk(presc_conv === 5'b10010 && presc_host === 5'b10010 && analog.p_prescale_hf__EN === 1'b0, "prescaler EN / one-hot ratio wrong");
  // receive chain
  setf(`F_LNA_STATE__STATE, 2); setf(`F_RXMIX_I_STATE__STATE, 2); setf(`F_RXMIX_Q_STATE__STATE, 2); setf(`F_CONSOLIDATION_BBFILTER__DIRECTION, 1);
  setf(`F_ADC_I_STATE__STATE, 2); setf(`F_ADC_Q_STATE__STATE, 2); setf(`F_REFBUF_STATE__STATE, 2); setf(`F_ADC_CONFIG__INTERLEAVE, 1);
  setf(`F_LNA_MATCH__ATT, 5'h15); setf(`F_LNA_MATCH__GAIN_LO, 1); setf(`F_BBFILTER_I_TRIM__GAIN, 9); setf(`F_BBFILTER_Q_TRIM__GAIN, 15);
  commit(1, "rf receive chain");
  chk(analog.p_lna__en && analog.p_core_bias__EN_lna && analog.p_rxmix_i__en && analog.p_rxmix_q__en && analog.p_bbfilter_i__en && analog.p_bbfilter_q__en &&
      analog.p_adc_i__EN && analog.p_adc_q__EN && analog.p_refbuf__EN && analog.p_adc_i__ILEN && analog.p_adc_q__ILEN, "rf receive: a block enable is missing");
  chk(analog.p_bbfilter_i__dir_tx === 1'b0 && lna_code === 6'h35, "rf receive: dir_tx set or the attenuator code wrong");
  chk(bbi_k === 6'd12 && {analog.p_bbfilter_i__gainc1, analog.p_bbfilter_i__gainc0} === 2'b01, "bbfilter_i PGA LUT: 21 dB is not k = 12, gainc0");
  chk(bbq_k === 6'd25 && {analog.p_bbfilter_q__gainc1, analog.p_bbfilter_q__gainc0} === 2'b11, "bbfilter_q PGA LUT: 39 dB is not k = 25, gainc0+1 (per-channel field)");
  chk(analog.p_txmix_i__en === 1'b0 && analog.p_rfdriver__en === 1'b0 && analog.p_wiredtx__SER_EN === 1'b0 && analog.p_pll_cdr__EN === 1'b0, "rf receive enabled a TX or wired block");
  setf(`F_BBFILTER_I_TRIM__CUT, 1); commit(1, "cut 1 with qt 6");
  setf(`F_BBFILTER_I_TRIM__QT, 3); commit(0, "FS-2 rule: cap code <= 1 with qt < 6 must be rejected");
  setf(`F_BBFILTER_I_TRIM__QT, 6); commit(1, "qt back to 6");
  // negative control: the rf island off forces every rf pin low, the configuration survives
  setf(`F_DEBUG_ISLAND_POWER__RF, 0); commit(1, "rf island off");
  chk(analog.p_lna__en === 0 && analog.p_rxmix_i__en === 0 && analog.p_bbfilter_i__en === 0 && lna_code === 6'd0 && bbi_k === 6'd0 && lna_ct === 4'd0,
      "rf island off: an rf pin is not 0");
  chk(analog.p_adc_i__EN === 1'b1, "rf island off switched the ADC (conv island) off");
  chk((ctl_all & `PT_TB_MASK_G1) === {$bits(ctl_all){1'b0}}, "rf group off: a control port that reaches an rf_rx / rf_tx / lo / lod cell is not 0 (TOP-25)");
  setf(`F_DEBUG_ISLAND_POWER__RF, 1); commit(1, "rf island on again");
  chk(analog.p_lna__en === 1'b1 && lna_code === 6'h35 && bbi_k === 6'd12, "rf configuration did not come back with the island");

  // ================= 3. RF transmit / duplex =================
  setf(`F_TXMIX_I_STATE__STATE, 2); setf(`F_TXMIX_Q_STATE__STATE, 2); setf(`F_TXSUM_STATE__STATE, 2); setf(`F_RFDRIVER_STATE__STATE, 2);
  setf(`F_DAC_I_STATE__STATE, 2); setf(`F_DAC_Q_STATE__STATE, 2);
  commit(0, "RC-16k rule: TX chain on with the LNA at full bias must be rejected");
  setf(`F_LNA_BIAS__LO, 1); commit(1, "duplex with reduced LNA bias");
  chk(analog.p_lna__lobias, "duplex: lobias"); chk(analog.p_txmix_i__en && analog.p_txmix_q__en, "duplex: txmix en"); chk(analog.p_txsum__en, "duplex: txsum en");
  chk(analog.p_rfdriver__en, "duplex: rfdriver en"); chk(analog.p_dac_i__EN && analog.p_dac_q__EN, "duplex: dac en");
  chk(analog.p_rfdriver__mute === 1'b1 && rfd_g === 4'd12, "rfdriver not muted by default or gain reset wrong");
  setf(`F_RFDRIVER_MUTE__MUTE, 0); setf(`F_DAC_I_CONFIG__HOLD_ZERO, 0); commit(1, "unmute register");
  chk(analog.p_rfdriver__mute === 1'b1, "rfdriver unmuted although the transport is not sending (transport mute is part of the gate)");
  force dut.rf_mute = 1'b0; #1;
  chk(analog.p_rfdriver__mute === 1'b0, "rfdriver mute did not release with register 0 and transport mute 0");
  fault_pin = 1; #1;
  chk(analog.p_rfdriver__mute === 1'b1 && analog.p_rfdriver__en === 1'b0 && analog.p_txmix_i__en === 1'b0 && analog.p_dac_i__HOLD_ZERO === 1'b1,
      "fault did not force the RF TX outputs off / muted");
  chk(analog.p_lna__en === 1'b1, "fault switched the receive chain off");
